// Mecanum Omnidirectional Robot
// Mixes one joystick's X/Y into four independent, correctly-signed motor speeds.

// Front-left motor (L298N "A", channel A)
const int FL_IN1 = 2, FL_IN2 = 3, FL_EN = 5;
// Front-right motor (L298N "A", channel B)
const int FR_IN1 = 4, FR_IN2 = 7, FR_EN = 6;
// Rear-left motor (L298N "B", channel A)
const int RL_IN1 = 8, RL_IN2 = 12, RL_EN = 10;
// Rear-right motor (L298N "B", channel B)
const int RR_IN1 = 13, RR_IN2 = A2, RR_EN = 11;

const int VRX_PIN = A0;
const int VRY_PIN = A1;
const int DEAD_ZONE = 60; // ignore small drift around joystick center

void setup() {
  int pins[] = {FL_IN1, FL_IN2, FR_IN1, FR_IN2, RL_IN1, RL_IN2, RR_IN1, RR_IN2,
                FL_EN, FR_EN, RL_EN, RR_EN};
  for (int i = 0; i < 12; i++) {
    pinMode(pins[i], OUTPUT);
  }
}

void loop() {
  // Rescale joystick readings to a signed -255..255 range, centered on 0.
  int x = map(analogRead(VRX_PIN), 0, 1023, -255, 255);
  int y = map(analogRead(VRY_PIN), 0, 1023, -255, 255);

  if (abs(x) < DEAD_ZONE) x = 0;
  if (abs(y) < DEAD_ZONE) y = 0;

  // Classic mecanum mixing: forward/back (Y) affects all wheels the same way;
  // strafe (X) affects diagonal pairs with opposite sign.
  int frontLeft  = constrain(y + x, -255, 255);
  int frontRight = constrain(y - x, -255, 255);
  int rearLeft   = constrain(y - x, -255, 255);
  int rearRight  = constrain(y + x, -255, 255);

  driveMotor(FL_IN1, FL_IN2, FL_EN, frontLeft);
  driveMotor(FR_IN1, FR_IN2, FR_EN, frontRight);
  driveMotor(RL_IN1, RL_IN2, RL_EN, rearLeft);
  driveMotor(RR_IN1, RR_IN2, RR_EN, rearRight);
}

// Drives one motor at a signed speed: positive = forward, negative = reverse.
void driveMotor(int in1, int in2, int enPin, int signedSpeed) {
  if (signedSpeed >= 0) {
    digitalWrite(in1, HIGH);
    digitalWrite(in2, LOW);
  } else {
    digitalWrite(in1, LOW);
    digitalWrite(in2, HIGH);
  }
  analogWrite(enPin, abs(signedSpeed));
}
